<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> TRUSTED_PROXIES=&quot;192.168.1.0/24&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
